CREATE TABLE IF NOT EXISTS media_evidence (id uuid PRIMARY KEY, storage_key text UNIQUE NOT NULL, media_type text NOT NULL CHECK (media_type IN ('HOUSE','BUSINESS','DOCUMENT')), upload_status text NOT NULL CHECK (upload_status IN ('PENDING','UPLOADED','FAILED')), is_private boolean NOT NULL DEFAULT true, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS geo_verifications (id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id), application_version integer NOT NULL, customer_id uuid NOT NULL REFERENCES customers(id), media_id uuid NOT NULL REFERENCES media_evidence(id), location geography(Point,4326) NOT NULL, latitude numeric(10,7) NOT NULL, longitude numeric(10,7) NOT NULL, accuracy_meters numeric(8,2) NOT NULL, captured_at timestamptz NOT NULL, status text NOT NULL CHECK (status IN ('PENDING','VALID','INVALID')), verified_at timestamptz, verified_by uuid REFERENCES users(id), created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS customer_locations (customer_id uuid PRIMARY KEY REFERENCES customers(id), location geography(Point,4326) NOT NULL, location_status text NOT NULL CHECK (location_status IN ('VALID','INVALID','PENDING')), source_geo_verification_id uuid REFERENCES geo_verifications(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS borrower_area_metrics (customer_id uuid PRIMARY KEY REFERENCES customers(id), loan_status text NOT NULL, risk_level text NOT NULL CHECK (risk_level IN ('LOW','MODERATE','HIGH','VERY_HIGH')), has_current_overdue boolean NOT NULL DEFAULT false, has_recent_delay boolean NOT NULL DEFAULT false, savings_trend text NOT NULL DEFAULT 'STABLE');
CREATE TABLE IF NOT EXISTS area_queries (id uuid PRIMARY KEY, application_id uuid NOT NULL REFERENCES applications(id), application_version integer NOT NULL, center geography(Point,4326) NOT NULL, radius_meters numeric(8,2) NOT NULL CHECK (radius_meters=500), cohort_count integer NOT NULL, outcome text NOT NULL CHECK (outcome IN ('READY','INSUFFICIENT_DATA','NO_NEARBY_BORROWERS_FOUND')), metrics jsonb NOT NULL DEFAULT '{}'::jsonb, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(application_id, application_version));
CREATE INDEX IF NOT EXISTS customer_locations_geo_idx ON customer_locations USING GIST(location);
